new='''// parseValue removes surrounding quotes or strips an inline comment.
// A quoted value ends at its closing quote, so a # inside is kept and a
// comment may follow. Inside quotes, \\" and \\\\ stand for a quote and a
// backslash. An unquoted value ends at the first #.
func parseValue(raw string) (string, error) {
	if !strings.HasPrefix(raw, `"`) {
		if i := strings.Index(raw, "#"); i >= 0 {
			raw = strings.TrimSpace(raw[:i])
		}
		return raw, nil
	}
	var sb strings.Builder
	for i := 1; i < len(raw); i++ {
		switch c := raw[i]; {
		case c == '\\\\' && i+1 < len(raw) && (raw[i+1] == '"' || raw[i+1] == '\\\\'):
			i++
			sb.WriteByte(raw[i])
		case c == '"':
			rest := strings.TrimSpace(raw[i+1:])
			if rest != "" && !strings.HasPrefix(rest, "#") {
				return "", fmt.Errorf("unexpected text after closing quote")
			}
			return sb.String(), nil
		default:
			sb.WriteByte(c)
		}
	}
	return "", fmt.Errorf("unterminated quoted value")
}
'''
s=s[:a]+new
open('parser.go','w').write(s)
E
